export default {
  name: 'TreeIcon',
  functional: true,
  props: {
    icon: {
      type: String,
      default: ''
    }
  },
  render: function render(h, context) {
    var icon = context.props.icon;
    var vnodes = [];
    if (icon) {
      vnodes.push(h("svg-icon", {
        "attrs": {
          "icon-class": icon
        }
      }));
    }
    return vnodes;
  }
};
